sys_script_include.script:
var DSOAiAuditUtil = Class.create();
DSOAiAuditUtil.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getCaseContext: function(caseSysId, advisorSysId) {
        var context = {};

        // 1. Get Visa Case Data
        var caseGr = new GlideRecord('x_snc_visaguardi_0_visa_case'); // Update to your actual case table name
        if (caseGr.get(caseSysId)) {
            context.caseNumber = caseGr.getValue('number') || 'VG-00125';
            context.caseStage = caseGr.getValue('stage') || 'Submitted';
            context.complianceStatus = caseGr.getValue('compliance_status') || 'On Track';
            context.riskLevel = caseGr.getValue('risk_score') || 'Medium';
            context.deadline = caseGr.getValue('sevis_deadline') || '14 Days';

            // Get related Student Profile
            var studentSysId = caseGr.getValue('student');
            var studentGr = new GlideRecord('x_snc_visaguardi_0_student_profile'); // Update to student table
            if (studentGr.get(studentSysId)) {
                context.studentName = studentGr.getValue('name');
            } else {
                context.studentName = "N/A";
            }
        }

		// 2. Retrieve Advisor Details from Advisor Profile Table
    var targetAdvisorSysId = advisorSysId || gs.getUserID();
    var contextAdvisor = {
        advisor_id: 'N/A',
        name: gs.getUserDisplayName(),
        email: gs.getUser().getEmail()
    };

    // Query your custom advisor profile table 
    // (Replace 'x_snc_visaguardi_0_advisor_profile' with your actual table name if different)
    var advGr = new GlideRecord('x_snc_visaguardi_0_advisor_profile');

    // Check if the table has a user reference field (e.g., 'user' or 'sys_user') or matches by sys_id
    advGr.addQuery('user', targetAdvisorSysId); // or advGr.addQuery('sys_id', targetAdvisorSysId);
    advGr.query();

    if (advGr.next()) {
        contextAdvisor.advisor_id = advGr.getValue('advisor_id') || advGr.getValue('number') || targetAdvisorSysId;
        contextAdvisor.name = advGr.getValue('name') || advGr.getDisplayValue('user') || '';
        contextAdvisor.email = advGr.getValue('email') || '';
    } else {
        // Fallback to sys_user if profile record isn't explicitly found
        var userGr = new GlideRecord('sys_user');
        if (userGr.get(targetAdvisorSysId)) {
            contextAdvisor.advisor_id = userGr.getValue('user_name') || targetAdvisorSysId;
            contextAdvisor.name = userGr.getValue('name') || '';
            contextAdvisor.email = userGr.getValue('email') || '';
        }
    }

    context.advisor = contextAdvisor;

        // 3. Get Document Statuses for this specific student's case
        var docs = [];
        // Change from 'document_configuration' to your actual student document instance table
        // (Usually named something like 'x_snc_visaguardi_0_visa_document' or 'x_snc_visaguardi_0_student_document')
        var docGr = new GlideRecord('x_snc_visaguardi_0_visa_document'); 

        // Query by the case reference or student reference field on the transaction record
        docGr.addQuery('case', caseSysId); // Or addQuery('student', studentSysId) depending on your schema
        docGr.query();

        while (docGr.next()) {
            docs.push({
                name: docGr.getValue('name') || docGr.getDisplayValue('document_type'),
                status: docGr.getDisplayValue('status') || docGr.getValue('status')
            });
        }

        // Fallback: If no documents found linked to the case, add a clean default note for the AI
        if (docs.length === 0) {
            docs.push({ name: "Required Documents", status: "Pending Verification" });
        }

        context.documents = docs;

        // 3. Get Case History / Audit Trail
        var history = [];
        var histGr = new GlideRecord('sys_audit'); // Or your custom case history table
        histGr.addQuery('documentkey', caseSysId);
        histGr.setLimit(5);
        histGr.query();
        while(histGr.next()) {
            history.push(histGr.getValue('fieldname') + ' changed to ' + histGr.getValue('newvalue'));
        }
        context.caseHistory = history;

        return context;
    },

    callLLM: function(systemPrompt, userPayload) {
        var apiKey = gs.getProperty('x_snc_visaguardi_0.visaguardian.ai.api_key');
        var endpoint = 'https://generativelanguage.googleapis.com/v1beta/models/gemini-flash-latest:generateContent?key=' + apiKey;

        try {
            var request = new sn_ws.RESTMessageV2();
            request.setEndpoint(endpoint);
            request.setHttpMethod('POST');
            request.setRequestHeader('Content-Type', 'application/json');

            var fullPrompt = systemPrompt + "\n\nCase Data Context:\n" + JSON.stringify(userPayload, null, 2);

            var requestBody = {
                contents: [{ role: "user", parts: [{ text: fullPrompt }] }],
                generationConfig: { temperature: 0.2 }
            };

            request.setRequestBody(JSON.stringify(requestBody));
            var response = request.execute();

            if (response.getStatusCode() === 200) {
                var parsed = JSON.parse(response.getBody());
                return { success: true, content: parsed.candidates[0].content.parts[0].text };
            } else {
                return { success: false, error: "VisaGuardian AI is temporarily unavailable. Please try again later." };
            }
        } catch (ex) {
            return { success: false, error: ex.getMessage() };
        }
    },

    generateCaseSummary: function() {
        var caseSysId = this.getParameter('sysparm_case_id');
        var advisorSysId = this.getParameter('sysparm_advisor_id'); // Optional if passed from client

        if (!caseSysId) return JSON.stringify({ success: false, error: 'Missing case ID' });

        var context = this.getCaseContext(caseSysId, advisorSysId);

        var systemPrompt = [
            "You are an expert Visa Compliance AI Auditor. Analyze the case data, including the assigned Advisor's metadata, and output a structured card using EXACTLY these 6 sections in Markdown:",
            "1. CASE SUMMARY",
            "A short 3–5 sentence explanation of the current situation.",
            "2. CURRENT STATUS",
            "List Case Stage, Compliance Status, Risk Level, Document Completion ratio, and Upcoming Deadline using clean bullet points.",
            "3. ADVISOR DETAILS",
            "List the Advisor ID, Advisor Name, and Advisor Email handling or reviewing this case audit trail.",
            "4. KEY ISSUES",
            "Identify 1-3 distinct points requiring advisor/DSO attention.",
            "5. DOCUMENT STATUS",
            "List documents with their status (e.g., ✓ Passport - Verified, ⚠ Financial Document - Pending Review).",
            "6. RECOMMENDED NEXT ACTIONS",
            "Provide specific, non-generic actions.",
            "",
            "Sources evaluated: ✓ Visa Case, ✓ Student Profile, ✓ Advisor Profile, ✓ Visa Documents, ✓ Risk Assessment, ✓ Deadlines"
        ].join("\n");

        var aiResult = this.callLLM(systemPrompt, context);
        return JSON.stringify(aiResult);
    },

    type: 'DSOAiAuditUtil'
});
